import json, hashlib
LOWER=[2,2,0,0,0,0,0,0]
UPPER=[4,4,4,4,4,4,4,4]
DEGREES=list(range(4,33)); HS=[1,2,3,4]; N=8

def wt(p): return sum(p)
def parts_rec(pos,prev,left,a):
    if pos==N:
        if left==0: yield tuple(a)
        return
    lo=LOWER[pos]; hi=min(prev,UPPER[pos],left)
    for x in range(hi,lo-1,-1):
        yield from parts_rec(pos+1,x,left-x,a+[x])
def parts(d): return list(parts_rec(0,UPPER[0],d,[]))
def horiz(lam,mu):
    # mu/lam horizontal iff mu_i >= lam_i >= mu_{i+1}, with padded length N
    return all(mu[i]>=lam[i] and lam[i]>= (mu[i+1] if i+1<N else 0) for i in range(N))
def ident(r,c): return [[1 if i==j else 0 for j in range(c)] for i in range(r)]
def shape(A): return [len(A),len(A[0]) if A else None]
def matmul(A, ar, ac, B, br, bc):
    assert ac==br
    return [[sum(A[i][k]*B[k][j] for k in range(ac)) for j in range(bc)] for i in range(ar)]
def zero(r,c): return [[0 for _ in range(c)] for _ in range(r)]
def addrow(A,i,j,q):
    for k in range(len(A[0]) if A else 0): A[i][k]+=q*A[j][k]
def addcol(A,i,j,q):
    for k in range(len(A)): A[k][i]+=q*A[k][j]
def swaprow(A,i,j): A[i],A[j]=A[j],A[i]
def swapcol(A,i,j):
    for row in A: row[i],row[j]=row[j],row[i]
def negrow(A,i):
    for k in range(len(A[0]) if A else 0): A[i][k]=-A[i][k]
def smith_unit(M,m,n):
    # This bounded family is reduced using only elementary integral operations at unit pivots.
    A=[row[:] for row in M]; U=ident(m,m); V=ident(n,n); log=[]; du=dv=1; k=0
    while True:
        pivot=None
        for i in range(k,m):
            for j in range(k,n):
                if abs(A[i][j])==1: pivot=(i,j); break
            if pivot: break
        if pivot is None: break
        i,j=pivot
        if i!=k:
            swaprow(A,k,i); swaprow(U,k,i); log.append(['rs',k,i]); du=-du
        if j!=k:
            swapcol(A,k,j); swapcol(V,k,j); log.append(['cs',k,j]); dv=-dv
        if A[k][k]==-1:
            negrow(A,k); negrow(U,k); log.append(['rn',k]); du=-du
        for i in range(k+1,m):
            if A[i][k]:
                q=-A[i][k]; addrow(A,i,k,q); addrow(U,i,k,q); log.append(['ra',i,k,q])
        for j in range(k+1,n):
            if A[k][j]:
                q=-A[k][j]; addcol(A,j,k,q); addcol(V,j,k,q); log.append(['ca',j,k,q])
        k+=1
    assert all(A[i][j]==0 for i in range(k,m) for j in range(k,n)), 'nonunit residual'
    D=zero(m,n)
    for i in range(k): D[i][i]=1
    return D,U,V,log,du,dv,k
def replay(M,m,n,log):
    A=[x[:] for x in M]; U=ident(m,m); V=ident(n,n)
    for z in log:
        if z[0]=='rs': swaprow(A,z[1],z[2]); swaprow(U,z[1],z[2])
        elif z[0]=='cs': swapcol(A,z[1],z[2]); swapcol(V,z[1],z[2])
        elif z[0]=='rn': negrow(A,z[1]); negrow(U,z[1])
        elif z[0]=='ra': addrow(A,z[1],z[2],z[3]); addrow(U,z[1],z[2],z[3])
        else: addcol(A,z[1],z[2],z[3]); addcol(V,z[1],z[2],z[3])
    return A,U,V
records=[]
for d in DEGREES:
    basis=parts(d); labels=[]; M=[]
    for h in HS:
        for lam in parts(d-h) if d>=h else []:
            labels.append([h,list(lam)])
            M.append([1 if horiz(lam,mu) else 0 for mu in basis])
    m,n=len(M),len(basis)
    # preserve n even when m=0; nested lists alone do not encode 0-by-n.
    D,U,V,ops,du,dv,rk=smith_unit(M,m,n)
    R,RU,RV=replay(M,m,n,ops)
    lhs=matmul(matmul(U,m,m,M,m,n),m,n,V,n,n)
    diagonal=all(D[i][j]==(1 if i==j and i<rk else 0) for i in range(m) for j in range(n))
    checks={'shapeCompatible':shape(M)==[m,(n if m else None)] and shape(D)==[m,(n if m else None)] and shape(U)==[m,(m if m else None)] and shape(V)==[n,(n if n else None)],'replayEqualsTracked':R==D and RU==U and RV==V,'UMVEqualsD':lhs==D,'diagonal':diagonal,'smithPositivityDivisibility':all(D[i][i]>0 for i in range(rk)) and all(D[i][i]%D[i-1][i-1]==0 for i in range(1,rk)),'unimodularU':du in (-1,1),'unimodularV':dv in (-1,1),'detU':du,'detV':dv}
    assert all(checks[x] for x in ['shapeCompatible','replayEqualsTracked','UMVEqualsD','diagonal','smithPositivityDivisibility','unimodularU','unimodularV'])
    records.append({'degree':d,'orderedBasis':[list(x) for x in basis],'rowLabels':labels,'matrixShape':[m,n],'M':M,'DShape':[m,n],'D':D,'UShape':[m,m],'VShape':[n,n],'V':V if d==4 else None,'operationLog':ops,'smithDiagonal':[D[i][i] for i in range(rk)],'rank':rk,'quotientFreeRank':n-rk,'torsionInvariantFactors':[],'zeroRowLabels':[labels[i] for i,row in enumerate(M) if not any(row)],'checks':checks})
# explicit boundary assertions required independently of JSON's empty-row ambiguity
r4=records[0]
assert r4['matrixShape']==[0,1] and r4['DShape']==[0,1] and r4['UShape']==[0,0] and r4['VShape']==[1,1] and r4['M']==[] and r4['D']==[] and r4['V']==[[1]] and r4['checks']['UMVEqualsD'] and r4['checks']['detV']==1
out={'inputs':{'lower':LOWER,'upper':UPPER,'degrees':DEGREES,'hDegrees':HS,'pieriRule':'coefficient 1 iff mu/lambda is a horizontal h-strip, equivalently mu_i >= lambda_i >= mu_(i+1), otherwise 0','columnOrder':'partition enumeration reverse lexicographic','rowOrder':'hDegrees input order then source partition reverse lexicographic'},'enumeratedAllSupportDegrees':True,'supportDegreeRange':[4,32],'degree4Boundary':{'MShape':[0,1],'DShape':[0,1],'UShape':[0,0],'VShape':[1,1],'M':[],'D':[],'U':[],'V':[[1]],'UMVEqualsD':True,'detV':1},'records':records}
payload=json.dumps(out,sort_keys=True,separators=(',',':'))
print(json.dumps({'outputSha256':hashlib.sha256(payload.encode()).hexdigest(),**out},sort_keys=True,separators=(',',':')))
